from pathlib import Path
p=Path('slides/03_comparison.tex');s=p.read_text();s=s.replace('We compare four model families that read sequences. We compare design choices, not experimental rankings.','We compare four families of sequence models. This compares design choices, not experimental results.').replace('\\fontsize{9.2}{11}','\\fontsize{9.2}{10.2}').replace('1.08','1.0').replace('\\[5pt]','\\[3pt]');s=s.replace('The gradient (learning signal) from early steps becomes very small in long sequences, so it forgets the distant past.','The learning signal from early steps becomes very small in long sequences. This vanishing gradient makes it forget the distant past.').replace('It has more parts and parameters, and still reads one step at a time, so training is slower and steps cannot run in parallel.','It has more parts and parameters. It reads one step at a time, so training is slower and steps cannot run in parallel.').replace('They see only the range covered by their filters; a past-only design cannot use future steps.','Their filters cover a limited time range. A past-only design cannot use future steps.').replace('Comparing all pairs makes cost grow with sequence length squared; it also needs time information and rules for allowed links.','Comparing all pairs makes cost grow with sequence length squared. It needs time codes and rules for allowed links.');p.write_text(s)
for name,width in [('02_pipeline', '.82'),('03_two_views','.82'),('04_network','.78'),('08_refinement','.78')]:
 for p in Path('slides').glob('*.tex'):
  s=p.read_text().replace('\\SlideFigure{'+name+'}', '\\SlideFigure['+width+'\\linewidth]{'+name+'}')
  s=s.replace('[u,g]&=', '\\relax [u,g]&=')
  p.write_text(s)
